import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))

from components.scan_precedence.work import compute


class TestScanPrecedence(unittest.TestCase):
    def test_public_fixture(self):
        payload = json.loads((ROOT / "components/scan_precedence/input.json").read_text())
        expected = json.loads((ROOT / "components/scan_precedence/expected.json").read_text())
        self.assertEqual(compute(payload), expected)

    def test_parent_before_child_same_depth_order(self):
        payload = {"scans": [{"finish": ["A/b/c", "A", "A/b", "B/x", "B"]}]}
        self.assertEqual(compute(payload), [["A", "B", "A/b", "B/x", "A/b/c"]])

    def test_multiple_rounds(self):
        payload = {"scans": [{"finish": ["X/y", "X"]}, {"finish": ["Z"]}]}
        self.assertEqual(compute(payload), [["X", "X/y"], ["Z"]])

    def test_empty(self):
        self.assertEqual(compute({}), [])
        self.assertEqual(compute({"scans": []}), [])


if __name__ == "__main__":
    import unittest
    unittest.main()

